/**
 * Groups the list items by a specified condition
 * Returns an array or arrays with grouped items.
 *
 * E.g.:
 * - groupBy(lodash.eq, [1, 1, 2, 3, 3, 4]) will be [[1,1], [2], [3,3], [4]]
 * - groupBy(lodash.gt, [1,3,2,1,5,7,6,4,8]) will be [[1], [3,2,1], [5], [7,6,4], [8]].
 *
 * @since ??
 *
 * @param {Function} fn Function to compare values.
 * @param {(number|string)[]} list Array of numbers to group.
 * @returns {(number|string)[]}
 */
export declare const groupBy: (fn: (lastItem: (number | string), item: (number | string)) => (number | string | boolean), list: number[]) => number[][];
